-- Path of Building
--
-- Module: zhTW Converter
-- Converts Taiwan server (pathofexile.tw) character-window API responses from
-- Traditional Chinese to English, so the rest of PoB (ModParser, Calc*) only ever sees English.
--
-- Lookup tables are generated by Export/Scripts/zhTW.lua into Data/zhTW/.
--
-- Public API:
--   ZhTW.convertCharacterList(list)    -- league names
--   ZhTW.convertItemsResponse(resp)    -- get-items response (items, guardian, character)
--   ZhTW.convertPassiveResponse(resp)  -- get-passive-skills response (jewels, tattoos)
--   ZhTW.getReport()                   -- lines that could not be converted by the last call
--   ZhTW.convertModLine(text)          -- single modifier (may contain "\n"); returns english or nil
--
local ipairs = ipairs
local pairs = pairs
local t_insert = table.insert
local t_concat = table.concat
local s_format = string.format
local m_floor = math.floor

local ZhTW = { }

local tables -- lazily loaded lookup tables
local report = { failures = { }, notes = { } }

local function loadTables()
	if tables then
		return tables
	end
	tables = {
		bases = LoadModule("Data/zhTW/Bases"),
		uniques = LoadModule("Data/zhTW/Uniques"),
		gems = LoadModule("Data/zhTW/Gems"),
		properties = LoadModule("Data/zhTW/Properties"),
		leagues = LoadModule("Data/zhTW/Leagues"),
		passives = LoadModule("Data/zhTW/Passives"),
		statDescriptions = LoadModule("Data/zhTW/StatDescriptions"),
	}
	return tables
end

local function trim(s)
	return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function addFailure(itemName, field, text)
	t_insert(report.failures, { item = itemName or "?", field = field, line = text })
end

local function addNote(text)
	t_insert(report.notes, text)
end

local function resetReport()
	report = { failures = { }, notes = { } }
end

-- Turns "前綴 {0} 後綴" into a matcher for that template; returns inner text or nil
local function stripTemplate(template, text)
	if not template then
		return nil
	end
	local pre, post = template:match("^(.-){0}(.*)$")
	if not pre then
		return nil
	end
	if #text > #pre + #post and text:sub(1, #pre) == pre and (post == "" or text:sub(-#post) == post) then
		return text:sub(#pre + 1, #text - #post)
	end
end

local function fillTemplate(template, value)
	return (template:gsub("{0}", function() return value end))
end

---------------------------------------------------------------------------
-- Name lookups
---------------------------------------------------------------------------

-- map value is either "English" or { "English1", "English2", ... } for ambiguous names.
-- validator(en) returns true when PoB knows the name; used to pick among candidates.
local function lookupName(map, zh, validator)
	local v = map[zh]
	if v == nil then
		return nil
	end
	if type(v) == "string" then
		return v
	end
	if validator then
		for _, en in ipairs(v) do
			if validator(en) then
				return en
			end
		end
	end
	return v[1]
end

local function gemValidator(en)
	return data.gemForBaseName and data.gemForBaseName[en:lower()] ~= nil
end

local function gemName(zh)
	if not zh or zh == "" then
		return nil
	end
	local gems = loadTables().gems
	return lookupName(gems, zh, gemValidator)
end

local treeNodeNames
local function passiveValidator(en)
	if not treeNodeNames then
		treeNodeNames = { }
		local tree = main and main.tree and latestTreeVersion and main.tree[latestTreeVersion]
		if tree and tree.nodes then
			for _, node in pairs(tree.nodes) do
				if node.dn then
					treeNodeNames[node.dn:lower()] = true
				end
			end
		end
	end
	return treeNodeNames[en:lower()] == true
end

local function passiveName(zh)
	return lookupName(loadTables().passives, zh, passiveValidator)
end

local function uniqueName(zh, baseName)
	local uniques = loadTables().uniques.uniques
	local v = uniques[zh]
	if type(v) == "table" then
		local db = main and main.uniqueDB and main.uniqueDB.byTitle
		if db then
			-- Prefer the candidate PoB knows with the same base type
			for _, en in ipairs(v) do
				local item = db[en:lower()]
				if item and (not baseName or item.baseName == baseName) then
					return en
				end
			end
			for _, en in ipairs(v) do
				if db[en:lower()] then
					return en
				end
			end
		end
		return v[1]
	end
	return v
end

local function iconArt(itemData)
	return itemData.icon and itemData.icon:match("([^/]+)%.png") or nil
end

local function baseExists(name)
	return data.itemBases[name] ~= nil or name == "Two-Toned Boots"
end

-- Picks the right English base for an ambiguous Chinese base name
local function resolveBase(zh, itemData)
	local v = loadTables().bases[zh]
	if v == nil then
		return nil
	end
	if type(v) == "string" then
		return v
	end
	local candidates = { }
	for _, c in ipairs(v) do
		if baseExists(c.name) then
			t_insert(candidates, c)
		end
	end
	if #candidates == 0 then
		return v[1].name
	elseif #candidates == 1 then
		return candidates[1].name
	end
	-- 1. Icon art
	local art = iconArt(itemData)
	if art then
		local byArt = { }
		for _, c in ipairs(candidates) do
			if c.art == art then
				t_insert(byArt, c)
			end
		end
		if #byArt == 1 then
			return byArt[1].name
		elseif #byArt > 1 then
			candidates = byArt
		end
	end
	-- 2. Required level: the item requirement can't be below the base requirement,
	--    so pick the highest base requirement that still fits
	local reqLevel
	for _, req in ipairs(itemData.requirements or { }) do
		if req.name == "Level" and req.values and req.values[1] then
			reqLevel = tonumber(tostring(req.values[1][1]):match("%d+"))
		end
	end
	if reqLevel then
		local best, bestLevel
		for _, c in ipairs(candidates) do
			local base = data.itemBases[c.name]
			local level = base and base.req and base.req.level or 0
			if level <= reqLevel and (not bestLevel or level > bestLevel) then
				best, bestLevel = c, level
			end
		end
		if best then
			addNote(s_format("Ambiguous base '%s' resolved to '%s' by required level %d", zh, best.name, reqLevel))
			return best.name
		end
	end
	addNote(s_format("Ambiguous base '%s' could not be resolved, using '%s'", zh, candidates[1].name))
	return candidates[1].name
end

