-- Special functions whose placeholder shows a name instead of a number
local nameSpecials = {
	passive_hash = "passive",
	display_indexable_support = "gem",
	display_indexable_non_active_support = "gem",
	display_indexable_skill = "gem",
	affliction_reward_type = "any",
	mod_value_to_item_class = "any",
	weapon_tree_unique_base_type_name = "any",
	tree_expansion_jewel_passive = "passive",
	affliction_notable = "passive",
	passive_hash_and_list = "passive",
	-- Newer clients: the name stands for a stat value (ring size, Timeless jewel faction / general).
	-- The value is looked up from the same description's other Chinese variants (see learnNameValues).
	passive_jewel_radius = "value",
	alternate_tree_version_name = "value",
	alternate_tree_version_keystone = "value",
}

-- Ring sizes the Taiwan site writes that the client's variants don't all list
-- ("巨大" is the older word for the Massive ring, "極大" the newer one)
local radiusNames = { ["小"] = 1, ["中"] = 2, ["大"] = 3, ["非常大"] = 4, ["極大"] = 5, ["巨大"] = 5 }

-- Reverse of the value transforms in Modules/StatDescriber.lua (displayed value -> stat value)
local inverse = {
	negate = function(v) return -v end,
	negate_and_double = function(v) return -v / 2 end,
	double = function(v) return v / 2 end,
	invert_chance = function(v) return 100 - v end,
	divide_by_two_0dp = function(v) return v * 2 end,
	divide_by_three = function(v) return v * 3 end,
	divide_by_four = function(v) return v * 4 end,
	divide_by_five = function(v) return v * 5 end,
	divide_by_six = function(v) return v * 6 end,
	divide_by_ten_0dp = function(v) return v * 10 end,
	divide_by_ten_1dp = function(v) return v * 10 end,
	divide_by_ten_1dp_if_required = function(v) return v * 10 end,
	divide_by_twelve = function(v) return v * 12 end,
	divide_by_fifteen_0dp = function(v) return v * 15 end,
	divide_by_twenty = function(v) return v * 20 end,
	divide_by_twenty_then_double_0dp = function(v) return v * 10 end,
	divide_by_one_hundred = function(v) return v * 100 end,
	divide_by_one_hundred_1dp = function(v) return v * 100 end,
	divide_by_one_hundred_2dp = function(v) return v * 100 end,
	divide_by_one_hundred_2dp_if_required = function(v) return v * 100 end,
	divide_by_one_hundred_and_negate = function(v) return -v * 100 end,
	divide_by_one_thousand = function(v) return v * 1000 end,
	per_minute_to_per_second = function(v) return v * 60 end,
	per_minute_to_per_second_0dp = function(v) return v * 60 end,
	per_minute_to_per_second_1dp = function(v) return v * 60 end,
	per_minute_to_per_second_2dp = function(v) return v * 60 end,
	per_minute_to_per_second_2dp_if_required = function(v) return v * 60 end,
	["permyriad_per_minute_to_%_per_second"] = function(v) return v * 6000 end,
	milliseconds_to_seconds = function(v) return v * 1000 end,
	milliseconds_to_seconds_0dp = function(v) return v * 1000 end,
	milliseconds_to_seconds_1dp = function(v) return v * 1000 end,
	milliseconds_to_seconds_2dp = function(v) return v * 1000 end,
	milliseconds_to_seconds_2dp_if_required = function(v) return v * 1000 end,
	deciseconds_to_seconds = function(v) return v * 10 end,
	locations_to_metres = function(v) return v * 10 end,
	["30%_of_value"] = function(v) return v / 0.3 end,
	["60%_of_value"] = function(v) return v / 0.6 end,
	multiplicative_damage_modifier = function(v) return v - 100 end,
	multiplicative_permyriad_damage_modifier = function(v) return (v - 100) * 100 end,
	multiply_by_four = function(v) return v / 4 end,
	times_one_point_five = function(v) return v / 1.5 end,
	times_twenty = function(v) return v / 20 end,
	plus_two_hundred = function(v) return v - 200 end,
	canonical_stat = function(v) return v end,
}

local function roundInt(v)
	if v >= 0 then
		return m_floor(v + 0.5)
	else
		return -m_floor(-v + 0.5)
	end
end

local function escapePattern(s)
	return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0"))
end

local NUMBER = "([%+%-]?%d[%d,]*%.?%d*)"
local NAME = "(.-)"

-- Compiles one Chinese template into a Lua pattern.
-- Returns nil for templates that can't be matched (e.g. only placeholders with no fixed text)
local function compileTemplate(text, nameIndex)
	text = text:gsub("%%%%", "%%")
	local parts = { "^" }
	local literal = { }
	local captureOf = { } -- placeholder index -> capture number
	local order = { } -- capture number -> placeholder index
	local fixed = 0
	local longest = ""
	local pos = 1
	local lineCount = 1
	local function addLiteral(s)
		if s == "" then
			return
		end
		-- "\n" in description files is a literal backslash-n
		local lines = { }
		s = s:gsub("\\n", "\n")
		for _ in s:gmatch("\n") do
			lineCount = lineCount + 1
		end
		fixed = fixed + #s
		for piece in (s .. "\n"):gmatch("([^\n]*)\n") do
			if #piece > #longest then
				longest = piece
			end
		end
		t_insert(parts, escapePattern(s))
	end
	while true do
		local s, e, inner = text:find("{([^}]*)}", pos)
		if not s then
			addLiteral(text:sub(pos))
			break
		end
		addLiteral(text:sub(pos, s - 1))
		local idx = tonumber(inner:match("^(%d+)")) or 0
		if captureOf[idx] then
			t_insert(parts, "%" .. captureOf[idx])
		else
			t_insert(order, idx)
			captureOf[idx] = #order
			t_insert(parts, nameIndex[idx + 1] and NAME or NUMBER)
		end
		pos = e + 1
	end
	t_insert(parts, "$")
	if #order > 9 then
		return nil
	end
	return {
		pattern = t_concat(parts),
		order = order,
		fixed = fixed,
		anchor = longest,
		lineCount = lineCount,
	}
end

local compiled -- list of compiled templates by line count
local limitOk, valueForLimit -- defined further down

-- For descriptions with "value" names: which stat values each Chinese name stands for.
-- A generic variant ("授銜{1}個硬幣以紀念{2} / 範圍內的天賦臣服於{0}") is lined up against the
-- specific ones ("5 # 3 1|# 授銜 {1} 個硬幣以紀念卡斯皮羅 / …臣服於不朽帝國"); each name captured
-- this way gets the specific variant's fixed stat values. Result: desc.zhNameValues[stat][name] = { [stat] = value }
local function learnNameValues(desc)
	local generics, specifics = { }, { }
	for _, variant in ipairs(desc.v or { }) do
		local names = { }
		for _, sp in ipairs(variant.p or { }) do
			if nameSpecials[sp[1]] == "value" then
				names[sp[2]] = sp[1]
			end
		end
		if next(names) then
			t_insert(generics, { variant = variant, names = names })
		else
			t_insert(specifics, variant)
		end
	end
	if #generics == 0 then
		return
	end
	local map = { }
	desc.zhNameValues = map
	for _, g in ipairs(generics) do
		-- names -> captures; numbers stay as "{n}" with optional spaces around them
		local parts, nameOrder = { "^" }, { }
		local pos, text = 1, g.variant.t
		while true do
			local a, b, inner = text:find("{([^}]*)}", pos)
			if not a then
				t_insert(parts, escapePattern(text:sub(pos)))
				break
			end
			t_insert(parts, escapePattern(text:sub(pos, a - 1)))
			local idx = (tonumber(inner:match("^(%d+)")) or 0) + 1
			if g.names[idx] then
				t_insert(parts, "(.-)")
				t_insert(nameOrder, idx)
			else
				t_insert(parts, "%s*{" .. (idx - 1) .. "[^}]*}%s*")
			end
			pos = b + 1
		end
		t_insert(parts, "$")
		local pattern = t_concat(parts)
		for _, sv in ipairs(specifics) do
			-- the specific variant must sit inside the generic one's fixed limits
			local fits = true
			for i, limit in ipairs(g.variant.l or { }) do
				if limit[1] ~= "#" and type(limit[1]) == "number" and not limitOk(sv.l[i] or { "#", "#" }, limit[1]) then
					fits = false
				end
			end
			local caps = fits and { sv.t:match(pattern) }
			if caps and caps[1] then
				local assign = { }
				for i, limit in ipairs(sv.l or { }) do
					if not (limit[1] == "#" and limit[2] == "#") then
						assign[i] = valueForLimit(limit, true)
					end
				end
				for k, idx in ipairs(nameOrder) do
					local name = trim(caps[k])
					map[idx] = map[idx] or { }
					map[idx][name] = map[idx][name] or assign
				end
			end
		end
		for idx, kind in pairs(g.names) do
			if kind == "passive_jewel_radius" then
				map[idx] = map[idx] or { }
				for name, v in pairs(radiusNames) do
					map[idx][name] = map[idx][name] or { [idx] = v }
				end
			end
		end
	end
end

local function compileAll()
	if compiled then
		return compiled
	end
	local statDesc = loadTables().statDescriptions
	compiled = { }
	for _, desc in ipairs(statDesc) do
		learnNameValues(desc)
		for _, variant in ipairs(desc.v or { }) do
			local nameIndex = { }
			for _, sp in ipairs(variant.p or { }) do
				if nameSpecials[sp[1]] then
					nameIndex[sp[2]] = sp[1]
				end
			end
			local c = compileTemplate(variant.t, nameIndex)
			if c and (c.fixed > 0) then
				c.desc = desc
				c.variant = variant
				c.nameIndex = nameIndex
				compiled[c.lineCount] = compiled[c.lineCount] or { }
				t_insert(compiled[c.lineCount], c)
			end
		end
	end
	return compiled
end

function limitOk(limit, value)
	if limit[1] == "!" then
		return value ~= limit[2]
	end
	if limit[1] ~= "#" and value < limit[1] then
		return false
	end
	if limit[2] ~= "#" and value > limit[2] then
		return false
	end
	return true
end

-- A value that satisfies a limit, for stats that are not shown in the text.
-- `present` asks for a non-zero value: a description with no number in it is only
-- shown when its stat is non-zero (e.g. "Has no Sockets" = 1).
function valueForLimit(limit, present)
	if limit[1] == "!" then
		return limit[2] == 0 and 1 or 0
	end
	if type(limit[1]) == "number" then
		return limit[1]
	end
	if type(limit[2]) == "number" then
		return (present and limit[2] >= 1) and 1 or math.min(limit[2], 0)
	end
	return present and 1 or 0
end

-- English name lookup for a "name" placeholder
local function translateNameValue(kind, zh)
	zh = trim(zh)
	if kind == "passive" then
		return passiveName(zh)
	elseif kind == "gem" then
		local en = gemName(zh) or gemName(zh .. "輔助")
		return en and (en:gsub(" Support$", ""))
	else
		local t = loadTables()
		return gemName(zh) or passiveName(zh) or lookupName(t.uniques.uniques, zh) or (type(t.bases[zh]) == "string" and t.bases[zh]) or nil
	end
end

local describer
local englishScopes = { }

local function getEnglishScope(name)
	if not englishScopes[name] then
		englishScopes[name] = LoadModule("Data/StatDescriptions/" .. name)
	end
	return englishScopes[name]
end

local function sameStats(a, b)
	if #a ~= #b then
		return false
	end
	for i = 1, #a do
		if a[i] ~= b[i] then
			return false
		end
	end
	return true
end

-- Renders English text for descriptors with name placeholders (StatDescriber can't do these)
local function renderNamed(desc, values, names)
	local fileName = loadTables().statDescriptions.files[desc.f]
	local scope = getEnglishScope(fileName)
	local enDesc
	local idx = scope[desc.s[1]]
	if idx and scope[idx] and scope[idx].stats and sameStats(scope[idx].stats, desc.s) then
		enDesc = scope[idx]
	else
		for _, d in ipairs(scope) do
			if d.stats and sameStats(d.stats, desc.s) then
				enDesc = d
				break
			end
		end
	end
	if not enDesc or not enDesc[1] then
		return nil
	end
	for _, variant in ipairs(enDesc[1]) do
		if not variant.gem_quality then
			local ok = true
			for i, limit in ipairs(variant.limit) do
				if not limitOk(limit, values[i] or 0) then
					ok = false
					break
				end
			end
			if ok then
				local text = variant.text:gsub("{(%d*):?(%+?)d?}", function(n, plus)
					local i = (tonumber(n) or 0) + 1
					if names[i] then
						return names[i]
					end
					local v = values[i] or 0
					return s_format(plus == "+" and "%+d" or "%d", v)
				end):gsub("%%%%", "%%")
				local lines = { }
				for line in (text .. "\\n"):gmatch("(.-)\\n") do
					t_insert(lines, line)
				end
				return t_concat(lines, "\n")
			end
		end
	end
end

-- Try to describe one candidate match in English
local function tryCandidate(c, captures, ignoreLimits)
	local desc, variant = c.desc, c.variant
	local nStats = #desc.s
	local values = { }
	local names = { }
	local shown = { }
	for capIndex, placeholder in ipairs(c.order) do
		local i = placeholder + 1
		local raw = captures[capIndex]
		shown[i] = true
		if c.nameIndex[i] and nameSpecials[c.nameIndex[i]] == "value" then
			local byName = c.desc.zhNameValues and c.desc.zhNameValues[i]
			local assign = byName and byName[trim(raw)]
			if not assign then
				return nil
			end
			for statIndex, v in pairs(assign) do
				if not shown[statIndex] or statIndex == i then
					values[statIndex] = values[statIndex] or v
				end
			end
			values[i] = assign[i] or values[i]
			if not values[i] then
				return nil
			end
		elseif c.nameIndex[i] then
			local en = translateNameValue(nameSpecials[c.nameIndex[i]], raw)
			if not en then
				return nil
			end
			names[i] = en
			values[i] = 1
		else
			local num = tonumber((raw:gsub(",", "")))
			if not num then
				return nil
			end
			values[i] = num
		end
	end
	-- Undo display transforms (applied in reverse order)
	local specials = variant.p or { }
	for k = #specials, 1, -1 do
		local name, statIndex = specials[k][1], specials[k][2]
		if not nameSpecials[name] and values[statIndex] and shown[statIndex] then
			local f = inverse[name]
			if f then
				values[statIndex] = f(values[statIndex])
			end
		end
	end
	for i = 1, nStats do
		if values[i] then
			if not names[i] then
				values[i] = roundInt(values[i])
			end
		else
			values[i] = valueForLimit(variant.l[i] or { "#", "#" }, #c.order == 0)
		end
		local limit = variant.l[i]
		if limit and not names[i] and not ignoreLimits and not limitOk(limit, values[i]) then
			return nil
		end
	end
	if next(names) then
		return renderNamed(desc, values, names)
	end
	-- Normal case: let PoB's own StatDescriber write the English line(s)
	describer = describer or LoadModule("Modules/StatDescriber")
	local stats = { }
	local any = false
	for i, stat in ipairs(desc.s) do
		if values[i] ~= 0 then
			stats[stat] = values[i]
			any = true
		end
	end
	if not any then
		return nil
	end
	local fileName = loadTables().statDescriptions.files[desc.f]
	local ok, out = pcall(describer, stats, fileName)
	if not ok or not out or #out == 0 then
		return nil
	end
	return t_concat(out, "\n")
end

-- Which mod kinds count for a modifier field (see Export/Scripts/zhTW.lua, desc.u)
local fieldKinds = {
	implicitMods = { "i" },
	enchantMods = { "n" },
	explicitMods = { "e", "q" },
	craftedMods = { "e" },
	fracturedMods = { "e" },
}
local function usageScore(desc, field)
	if not desc.u then
		return 0
	end
	local score = 0
	for _, kind in ipairs(fieldKinds[field] or { "i", "e", "q", "n" }) do
		score = score + (desc.u[kind] or 0)
	end
	return score
end

-- Item being converted: its base tags decide between stats that share one Chinese text
local itemContext

local function normaliseModLine(line)
	return (line:lower():gsub("%(%-?[%d%.]+%-%-?[%d%.]+%)", "#"):gsub("[%+%-]?%d+%.?%d*", "#"):gsub("[%+%-]#", "#"):gsub("%s+", " "))
end

local modIndex -- normalised English mod line -> list of mod definitions
local function getModIndex()
	if modIndex then
		return modIndex
	end
	modIndex = { }
	local sets = { }
	for _, key in ipairs({ "Explicit", "ItemExclusive", "Corrupted", "Delve", "Synthesis", "Scourge", "Eldritch",
			"Flask", "Tincture", "Jewel", "JewelAbyss", "JewelCluster", "Foulborn" }) do
		t_insert(sets, data.itemMods[key])
	end
	t_insert(sets, data.masterMods)
	for _, set in ipairs(sets) do
		for _, mod in pairs(set or { }) do
			for i = 1, #mod do
				if type(mod[i]) == "string" then
					local key = normaliseModLine(mod[i])
					modIndex[key] = modIndex[key] or { }
					t_insert(modIndex[key], mod)
				end
			end
		end
	end
	return modIndex
end

local enchantIndex -- normalised English enchantment lines (cluster jewels, labyrinth, flasks...)
local function getEnchantIndex()
	if enchantIndex then
		return enchantIndex
	end
	enchantIndex = { }
	local function add(line)
		if type(line) == "string" then
			enchantIndex[normaliseModLine(line)] = true
		end
	end
	for _, jewel in pairs(data.clusterJewels and data.clusterJewels.jewels or { }) do
		for _, skill in pairs(jewel.skills or { }) do
			for _, line in ipairs(skill.enchant or { }) do
				add(line)
			end
		end
	end
	local function walk(t, depth)
		if depth > 4 then return end
		for _, v in pairs(t) do
			if type(v) == "string" then add(v) elseif type(v) == "table" then walk(v, depth + 1) end
		end
	end
	walk(data.enchantments or { }, 1)
	return enchantIndex
end

-- Score of an English candidate for the field it came from:
-- explicit-type fields: 2 = a mod with this text can roll on the current item, 1 = known mod, 0 = unknown
-- enchantMods: 2 = a known enchantment line
-- other fields: 0 (the mod usage ranking from the export decides)
local explicitFields = { explicitMods = true, craftedMods = true, fracturedMods = true }
local function knownModScore(en, field)
	if field == "enchantMods" then
		local index = getEnchantIndex()
		for line in (en .. "\n"):gmatch("([^\n]*)\n") do
			if index[normaliseModLine(line)] then
				return 2
			end
		end
		return 0
	end
	if not explicitFields[field] then
		return 0
	end
	local index = getModIndex()
	local score = 0
	for line in (en .. "\n"):gmatch("([^\n]*)\n") do
		for _, mod in ipairs(index[normaliseModLine(line)] or { }) do
			local s = 1
			if itemContext and mod.weightKey then
				for k, key in ipairs(mod.weightKey) do
					if itemContext.tags[key] and (mod.weightVal[k] or 0) > 0 then
						s = 2
						break
					end
				end
			end
			if s > score then
				score = s
			end
		end
	end
	return score
end

local function makeItemContext(baseEn, itemData)
	local base = baseEn and data.itemBases[baseEn]
	if not base then
		return nil
	end
	local ctx = { name = baseEn, tags = copyTable(base.tags or { }) }
	local sig = { baseEn }
	if type(itemData.influences) == "table" and base.influenceTags then
		for _, info in ipairs(itemLib.influenceInfo.all) do
			if itemData.influences[info.display:lower()] and base.influenceTags[info.key] then
				ctx.tags[base.influenceTags[info.key]] = true
				t_insert(sig, info.key)
			end
		end
	end
	ctx.sig = t_concat(sig, ",")
	return ctx
end

-- Matches text against templates with the given number of lines.
-- field is the API field the line came from (implicitMods, explicitMods, ...), used to
-- choose between different stats that share the same Chinese text.
local function matchText(text, lineCount, field)
	local list = compileAll()[lineCount]
	if not list then
		return nil
	end
	local candidates = { }
	for _, c in ipairs(list) do
		if text:find(c.anchor, 1, true) then
			local caps = { text:match(c.pattern) }
			if caps[1] ~= nil or (#c.order == 0 and text:match(c.pattern)) then
				t_insert(candidates, { c = c, caps = caps })
			end
		end
	end
	if #candidates == 0 then
		return nil
	end
	-- Most specific first: longest fixed text, then the main stat_descriptions file
	table.sort(candidates, function(a, b)
		if a.c.fixed ~= b.c.fixed then
			return a.c.fixed > b.c.fixed
		end
		local ua, ub = usageScore(a.c.desc, field), usageScore(b.c.desc, field)
		if ua ~= ub then
			return ua > ub
		end
		return a.c.desc.f < b.c.desc.f
	end)
	local best, bestCand
	for _, cand in ipairs(candidates) do
		local en = tryCandidate(cand.c, cand.caps)
		if en then
			best, bestCand = en, cand
			break
		end
	end
	if best then
		-- Different stats can share one Chinese text. If an equally specific candidate gives
		-- different English, prefer the one PoB's mod data allows on this kind of item.
		local alternatives = { best }
		for _, cand in ipairs(candidates) do
			if cand ~= bestCand and cand.c.fixed == bestCand.c.fixed and cand.c.desc ~= bestCand.c.desc then
				local en = tryCandidate(cand.c, cand.caps)
				if en and not isValueInArray(alternatives, en) then
					t_insert(alternatives, en)
				end
			end
		end
		if #alternatives > 1 and itemContext then
			local bestScore = knownModScore(best, field)
			for i = 2, #alternatives do
				local score = knownModScore(alternatives[i], field)
				if score > bestScore then
					best, bestScore = alternatives[i], score
				end
			end
			addNote(s_format("Ambiguous '%s' on %s: chose '%s' from { %s }", text, itemContext.name, best, t_concat(alternatives, " | ")))
		end
		return best
	end
	-- The website sometimes shows values outside the range the client text allows
	-- (e.g. "+102%" on a line whose template is for 1-99). Use the best match anyway;
	-- StatDescriber then picks the English wording for the actual value.
	for _, cand in ipairs(candidates) do
		local en = tryCandidate(cand.c, cand.caps, true)
		if en then
			addNote(s_format("Value outside template range, converted anyway: %s => %s", text, en))
			return en
		end
	end
end

-- Lines that are prefixed by fixed text and contain another modifier
local prefixRules = {
	{ zh = "附加的小型天賦給予：", en = "Added Small Passive Skills grant: " },
}

local cache = { }

-- Converts a (possibly multi-line) modifier. Returns English or nil.
-- Newer Taiwan data has keyword links in mod texts: "+8%[PlayerItemRarity|物品稀有度]"
local function stripLinks(s)
	if type(s) ~= "string" or not s:find("[", 1, true) then
		return s
	end
	return (s:gsub("%[([^%[%]|]+)|([^%[%]]+)%]", "%2"):gsub("%[([^%[%]|]+)%]", "%1"))
end
ZhTW.stripLinks = stripLinks

-- The Taiwan site sends some lines half translated: a Chinese prefix and the rest in English
-- ("附加的小型天賦給予：Minions have 12% increased maximum Life" on cluster jewels).
local mixedPrefixes = {
	{ zh = "附加的小型天賦給予：", en = "Added Small Passive Skills grant: " },
	{ zh = "附加的小型天賦給予:", en = "Added Small Passive Skills grant: " },
}

local function convertModText(text, field)
	text = stripLinks(text)
	for _, prefix in ipairs(mixedPrefixes) do
		if text:sub(1, #prefix.zh) == prefix.zh then
			local rest = text:sub(#prefix.zh + 1)
			if rest:find("%a") and not rest:find("[\128-\255]") then
				return prefix.en .. rest
			end
		end
	end
	local cacheKey = text .. "|" .. tostring(field) .. "|" .. (itemContext and itemContext.sig or "")
	if cache[cacheKey] ~= nil then
		return cache[cacheKey] or nil
	end
	local lines = { }
	for line in (text .. "\n"):gmatch("([^\n]*)\n") do
		t_insert(lines, line)
	end
	local result
	-- Whole text first, then greedy spans of up to 3 lines
	result = matchText(text, #lines, field)
	if not result and #lines > 1 then
		local out = { }
		local i = 1
		local ok = true
		while i <= #lines do
			local done = false
			for span = math.min(3, #lines - i + 1), 1, -1 do
				local chunk = t_concat(lines, "\n", i, i + span - 1)
				local en = (span < #lines or i > 1) and matchText(chunk, span, field)
				if en then
					t_insert(out, en)
					i = i + span
					done = true
					break
				end
			end
			if not done then
				ok = false
				break
			end
		end
		if ok then
			result = t_concat(out, "\n")
		end
	end
	if not result and #lines == 1 then
		for _, rule in ipairs(prefixRules) do
			if text:sub(1, #rule.zh) == rule.zh then
				local inner = convertModText(text:sub(#rule.zh + 1), field)
				if inner and not inner:find("\n") then
					result = rule.en .. inner
				end
			end
		end
	end
	cache[cacheKey] = result or false
	return result
end

function ZhTW.convertModLine(text, field)
	return convertModText(text, field)
end

-- Converts an array of modifiers (strings or { description = ... } tables) in place
local modFields = { "implicitMods", "explicitMods", "craftedMods", "enchantMods", "fracturedMods",
	"utilityMods", "scourgeMods", "crucibleMods", "mutatedMods", "veiledMods" }

local function convertModList(list, itemName, field)
	if type(list) ~= "table" then
		return
	end
	local function getText(m)
		return type(m) == "table" and m.description or m
	end
	local function setText(i, text)
		if type(list[i]) == "table" then
			list[i].description = text
		else
			list[i] = text
		end
	end
	local failed = { }
	for i, m in ipairs(list) do
		local text = getText(m)
		if type(text) == "string" and text ~= "" then
			local en = convertModText(text, field)
			if en then
				setText(i, en)
			else
				failed[i] = true
			end
		end
	end
	-- Some descriptions span two API lines: retry neighbouring failures together
	local i = 1
	while i < #list do
		if failed[i] and failed[i + 1] then
			local en = convertModText(getText(list[i]) .. "\n" .. getText(list[i + 1]), field)
			if en then
				setText(i, en)
				table.remove(list, i + 1)
				table.remove(failed, i + 1)
				failed[i] = nil
				local shifted = { }
				for k in pairs(failed) do
					shifted[k > i and k - 1 or k] = true
				end
				failed = shifted
			end
		end
		i = i + 1
	end
	for k in pairs(failed) do
		local text = getText(list[k])
		for line in (text .. "\n"):gmatch("([^\n]*)\n") do
			if line ~= "" and not convertModText(line, field) then
				addFailure(itemName, field, line)
			end
		end
		-- Keep the line, converting any parts that do match
		local parts = { }
		for line in (text .. "\n"):gmatch("([^\n]*)\n") do
			t_insert(parts, convertModText(line, field) or line)
		end
		setText(k, t_concat(parts, "\n"))
	end
end

---------------------------------------------------------------------------
-- Items
---------------------------------------------------------------------------

local function convertProperties(list, itemName)
	if type(list) ~= "table" then
		return
	end
	local props = loadTables().properties
	for _, prop in ipairs(list) do
		if type(prop.name) == "string" and prop.name ~= "" then
			local en = props.names[prop.name]
			if en then
				local isRadius = en == "Radius"
				prop.name = en
				if isRadius and prop.values then
					for _, v in ipairs(prop.values) do
						if type(v[1]) == "string" and props.values[v[1]] then
							v[1] = props.values[v[1]]
						end
					end
				end
			end
		end
	end
end

local function convertRareName(zh)
	local words = loadTables().uniques.words
	local out = { }
	for word in zh:gmatch("%S+") do
		local en = lookupName(words, word)
		if not en then
			return nil
		end
		t_insert(out, en)
	end
	return #out > 0 and t_concat(out, " ") or nil
end

local convertItem

local function convertGem(gem, itemName)
	local props = loadTables().properties
	local typeEn = gemName(gem.typeLine)
	local hybridEn
	if gem.hybrid and gem.hybrid.baseTypeName then
		hybridEn = gemName(gem.hybrid.baseTypeName)
		if hybridEn then
			gem.hybrid.baseTypeName = hybridEn
		end
	end
	if typeEn then
		gem.typeLine = typeEn
	end
	if gem.baseType then
		gem.baseType = gemName(gem.baseType) or gem.baseType
	end
	if not typeEn and not hybridEn then
		addFailure(itemName, "gem", gem.typeLine)
	end
	convertProperties(gem.properties, itemName)
	convertProperties(gem.requirements, itemName)
	if type(gem.builtInSupport) == "string" then
		gem.builtInSupport = stripLinks(gem.builtInSupport)
		local t = props.templates.ItemDisplayBuiltInSupport
		local inner = t and stripTemplate(t.zh, gem.builtInSupport)
		local en = inner and (gemName(inner .. "輔助") or gemName(inner))
		if en then
			gem.builtInSupport = fillTemplate(t.en, (en:gsub(" Support$", "")))
		else
			addFailure(itemName, "builtInSupport", gem.builtInSupport)
		end
	end
end

convertItem = function(itemData)
	local t = loadTables()
	local props = t.properties
	local displayName = (itemData.name ~= "" and itemData.name) or itemData.typeLine or "?"

	-- Base type
	local typeLine = itemData.typeLine or ""
	local enPrefix = ""
	for _, id in ipairs({ "SynthesisedItem", "DivergentItem" }) do
		local tmpl = props.templates[id]
		local inner = tmpl and stripTemplate(tmpl.zh, typeLine)
		if inner then
			enPrefix = tmpl.en:gsub("{0}.*$", "")
			typeLine = inner
			break
		end
	end
	local baseZh = itemData.baseType
	if not baseZh or baseZh == "" then
		-- Find the longest base name contained in the type line (magic items)
		local best
		for zh in pairs(t.bases) do
			if (not best or #zh > #best) and typeLine:find(zh, 1, true) then
				best = zh
			end
		end
		baseZh = best
	end
	local baseEn = baseZh and resolveBase(baseZh, itemData)
	local outerContext = itemContext
	itemContext = makeItemContext(baseEn, itemData)
	if baseEn then
		itemData.baseType = baseEn
		if itemData.name ~= "" then
			itemData.typeLine = enPrefix .. baseEn
		else
			-- Magic / normal items: affix names are cosmetic, the mods carry the stats
			itemData.typeLine = enPrefix .. baseEn
		end
	else
		addFailure(displayName, "baseType", itemData.baseType or itemData.typeLine)
	end

	-- Item name
	if itemData.name and itemData.name ~= "" then
		local frame = itemData.frameType
		if frame == 3 or frame == 9 or frame == 10 then
			local name = itemData.name
			local foulborn = props.templates.MutatedUniqueName
			local inner = foulborn and stripTemplate(foulborn.zh, name)
			local en = uniqueName(name, baseEn)
			if not en and inner then
				local innerEn = uniqueName(inner, baseEn)
				en = innerEn and fillTemplate(foulborn.en, innerEn)
			end
			if en then
				itemData.name = en
			else
				addFailure(displayName, "name", itemData.name)
			end
		else
			-- Rare names are cosmetic; fall back to the base name so the UI shows readable text
			itemData.name = convertRareName(itemData.name) or baseEn or itemData.name
		end
	end

	convertProperties(itemData.properties, displayName)
	convertProperties(itemData.requirements, displayName)
	convertProperties(itemData.additionalProperties, displayName)
	for _, field in ipairs(modFields) do
		convertModList(itemData[field], displayName, field)
	end
	if itemData.socketedItems then
		for _, socketed in ipairs(itemData.socketedItems) do
			if socketed.abyssJewel or socketed.frameType ~= 4 then
				convertItem(socketed)
			else
				convertGem(socketed, displayName)
			end
		end
	end
	itemContext = outerContext
	return itemData
end

local function safeConvertItem(itemData)
	local ok, err = pcall(convertItem, itemData)
	itemContext = nil
	if not ok then
		addFailure(itemData.name or itemData.typeLine, "error", tostring(err))
	end
end

---------------------------------------------------------------------------
-- Leagues
---------------------------------------------------------------------------

local function convertLeague(zh)
	if type(zh) ~= "string" or zh == "" then
		return zh
	end
	local t = loadTables().leagues
	local en = lookupName(t.names, zh)
	if en then
		return en
	end
	local hc = t.modes.CreateCharacterStateHardcore
	if hc and zh == hc.zh then
		return "Hardcore"
	end
	-- Seasonal league: find the short league name inside the full name.
	-- LeagueNames.dat can lag behind a new league; its full names ("巫影密會聯盟「自力」" =
	-- "SSF Coven") give the short name too.
	if not t.shortFromNames then
		t.shortFromNames = true
		local known = { }
		for _, s in ipairs(t.short) do
			known[s.zh] = true
		end
		for zhName, enName in pairs(t.names) do
			local zhShort = type(zhName) == "string" and zhName:match("^(.-)聯盟「自力」$")
			local enShort = type(enName) == "string" and enName:match("^SSF (.+)$")
			if zhShort and enShort and zhShort ~= "" and not enShort:match("^HC ") and not known[zhShort] then
				known[zhShort] = true
				t_insert(t.short, { zh = zhShort, en = enShort })
			end
		end
	end
	local best
	for _, s in ipairs(t.short) do
		if zh:find(s.zh, 1, true) and (not best or #s.zh > #best.zh) then
			best = s
		end
	end
	if not best then
		addFailure("league", "league", zh)
		return zh
	end
	local isHC = zh:find("專家", 1, true) ~= nil
	local isSSF = zh:find("自力", 1, true) ~= nil
	local isRuthless = zh:find("殘暴", 1, true) ~= nil
	local prefix
	if isHC and isSSF then
		prefix = isRuthless and "HC SSF R " or "HC SSF "
	elseif isSSF then
		prefix = isRuthless and "SSF R " or "SSF "
	elseif isHC then
		prefix = isRuthless and "HC Ruthless " or "Hardcore "
	elseif isRuthless then
		prefix = "Ruthless "
	else
		prefix = ""
	end
	return prefix .. best.en
end

---------------------------------------------------------------------------
-- Public API
---------------------------------------------------------------------------

function ZhTW.convertCharacterList(list)
	resetReport()
	for _, char in ipairs(list or { }) do
		char.league = convertLeague(char.league)
	end
	return list
end

function ZhTW.convertItemsResponse(resp)
	resetReport()
	if type(resp) ~= "table" then
		return resp
	end
	for _, itemData in ipairs(resp.items or { }) do
		safeConvertItem(itemData)
	end
	for _, itemData in ipairs(resp.guardian or { }) do
		safeConvertItem(itemData)
	end
	if resp.character then
		resp.character.league = convertLeague(resp.character.league)
	end
	return resp
end

function ZhTW.convertPassiveResponse(resp)
	resetReport()
	if type(resp) ~= "table" then
		return resp
	end
	for _, itemData in ipairs(resp.items or { }) do
		safeConvertItem(itemData)
	end
	-- Tattoos: PoB looks them up by English name
	if type(resp.skill_overrides) == "table" then
		local bases = loadTables().bases
		for nodeId, override in pairs(resp.skill_overrides) do
			if type(override) == "table" and override.name then
				local en = bases[override.name]
				if type(en) == "table" then
					en = en[1].name
				end
				if en then
					override.name = en
					if type(override.stats) == "table" then
						for i, stat in ipairs(override.stats) do
							override.stats[i] = convertModText(stat) or stat
						end
					end
				else
					-- An unknown name would break the import; drop the override instead
					addFailure("tattoo " .. tostring(nodeId), "skill_overrides", override.name)
					resp.skill_overrides[nodeId] = nil
				end
			end
		end
	end
	if resp.character and type(resp.character) == "table" then
		resp.character.league = convertLeague(resp.character.league)
	end
	return resp
end

-- { failures = { { item, field, line } ... }, notes = { ... } }
function ZhTW.getReport()
	return report
end

-- Used by Modules/ZhTWItemText.lua (in-game Ctrl+C item text):
-- converts base type and item name of an API-like item table without any modifier fields
function ZhTW.convertItemHeader(itemData)
	resetReport()
	safeConvertItem(itemData)
	return itemData
end

-- Sets the item the following convertModLine calls are for (mods that share a Chinese text)
function ZhTW.setItemContext(baseEn)
	itemContext = baseEn and makeItemContext(baseEn, { }) or nil
end

function ZhTW.getTables()
	return loadTables()
end

-- Prints the report to the console; returns the number of failed lines
function ZhTW.printReport(label)
	local r = report
	for _, note in ipairs(r.notes) do
		ConPrintf("[zhTW] %s", note)
	end
	if #r.failures > 0 then
		ConPrintf("[zhTW] %s: %d line(s) could not be converted:", label or "Import", #r.failures)
		for _, f in ipairs(r.failures) do
			ConPrintf("[zhTW]   %s [%s] %s", f.item, f.field, f.line)
		end
	end
	return #r.failures
end

-- Shared with Modules/ZhTWMods.lua (English -> Chinese display)
ZhTW.internal = {
	compileTemplate = compileTemplate,
	inverse = inverse,
	nameSpecials = nameSpecials,
	roundInt = roundInt,
	limitOk = limitOk,
	valueForLimit = valueForLimit,
}

return ZhTW
